// Practical AI study guide. Prompting advice checked against Google's and Anthropic's prompting docs, and the
// frameworks section against the NIST and EU AI Act pages, on 2026-11-22 (see tools/config.js sources).
// Deliberately contains no model names, prices, limits or benchmarks: those change and are not verifiable here.
// Inline quiz markup is generated by quiz() so it matches the other guides.

const esc = (t) => String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

